package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

// 01 ORDER-REC, 15 bytes
type OrderRec struct {
	OrId    string          // PIC X(5) @0 len=5
	OrStat  string          // PIC X(1) @5 len=1
	OrQty   int64           // PIC 9(3) @6 len=3
	OrPrice decimal.Decimal // PIC 9(4)V99 @9 len=6
}

var WsEofFlag string = "N"                           // PIC X len=1 = "N"
var WsTotal decimal.Decimal = decimal.NewFromInt(0)   // PIC 9(8)V99 len=10 = 0
var WsGrand decimal.Decimal = decimal.NewFromInt(0)   // PIC 9(10)V99 len=12 = 0
var WsNewCount int64 = 0                              // PIC 99 len=2 = 0
var WsShipCount int64 = 0                             // PIC 99 len=2 = 0
var WsCancelCount int64 = 0                           // PIC 99 len=2 = 0
var WsInvalid int64 = 0                               // PIC 99 len=2 = 0
var WsBadQty int64 = 0                                // PIC 99 len=2 = 0
var WsQtyEd string                                    // PIC ZZ9 len=3
var WsPriceEd string                                  // PIC Z,ZZ9.99 len=8
var WsTotalEd string                                  // PIC ZZ,ZZZ,ZZ9.99 len=13
var WsGrandEd string                                  // PIC Z,ZZZ,ZZZ,ZZ9.99 len=16

var orderFile *os.File
var orderScanner *bufio.Scanner
var curRec OrderRec

func storeDecimal(val decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	v := val.Truncate(int32(scale))
	isNeg := v.Sign() < 0
	av := v.Abs()
	pow10scale := decimal.New(1, int32(scale))
	scaled := av.Mul(pow10scale).Truncate(0)
	scaledStr := scaled.StringFixed(0)
	totalDigits := intDigits + scale
	if len(scaledStr) > totalDigits {
		scaledStr = scaledStr[len(scaledStr)-totalDigits:]
	}
	var newStr string
	if scale == 0 {
		newStr = scaledStr
	} else {
		if len(scaledStr) <= scale {
			newStr = "0." + strings.Repeat("0", scale-len(scaledStr)) + scaledStr
		} else {
			newStr = scaledStr[:len(scaledStr)-scale] + "." + scaledStr[len(scaledStr)-scale:]
		}
	}
	d, _ := decimal.NewFromString(newStr)
	if isNeg {
		d = d.Neg()
	}
	return d
}

func formatEdited(val decimal.Decimal, picture string) string {
	dotIdx := strings.Index(picture, ".")
	var intPic string
	decSlots := 0
	if dotIdx != -1 {
		intPic = picture[:dotIdx]
		decSlots = len(picture) - dotIdx - 1
	} else {
		intPic = picture
	}
	intSlots := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intSlots++
		}
	}
	av := val.Abs()
	avTrunc := av.Truncate(int32(decSlots))
	pow10 := decimal.New(1, int32(decSlots))
	scaled := avTrunc.Mul(pow10).Truncate(0)
	scaledStr := scaled.StringFixed(0)

	var intPartStr string
	var fracPartStr string
	if decSlots > 0 {
		if len(scaledStr) <= decSlots {
			intPartStr = "0"
			fracPartStr = strings.Repeat("0", decSlots-len(scaledStr)) + scaledStr
		} else {
			intPartStr = scaledStr[:len(scaledStr)-decSlots]
			fracPartStr = scaledStr[len(scaledStr)-decSlots:]
		}
	} else {
		intPartStr = scaledStr
		fracPartStr = ""
	}
	if len(intPartStr) > intSlots {
		intPartStr = intPartStr[len(intPartStr)-intSlots:]
	} else if len(intPartStr) < intSlots {
		intPartStr = strings.Repeat("0", intSlots-len(intPartStr)) + intPartStr
	}
	var buf strings.Builder
	digitIdx := 0
	stillSuppressing := true
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			d := intPartStr[digitIdx]
			digitIdx++
			if ch == 'Z' {
				if d == '0' && stillSuppressing {
					buf.WriteByte(' ')
				} else {
					buf.WriteByte(d)
					stillSuppressing = false
				}
				if d != '0' {
					stillSuppressing = false
				}
			} else { // '9'
				buf.WriteByte(d)
				stillSuppressing = false
			}
		} else if ch == ',' {
			if stillSuppressing {
				buf.WriteByte(' ')
			} else {
				buf.WriteByte(',')
			}
		} else {
			buf.WriteByte(byte(ch))
		}
	}
	intFormatted := buf.String()
	if decSlots > 0 {
		return intFormatted + "." + fracPartStr
	}
	return intFormatted
}

func READ_PARA() {
	if orderScanner == nil {
		WsEofFlag = "Y"
		return
	}
	if orderScanner.Scan() {
		txt := orderScanner.Text()
		if len(txt) < 15 {
			txt = txt + strings.Repeat(" ", 15-len(txt))
		} else if len(txt) > 15 {
			txt = txt[:15]
		}
		curRec.OrId = txt[0:5]
		curRec.OrStat = txt[5:6]
		qtyStr := txt[6:9]
		qtyTrim := strings.TrimSpace(qtyStr)
		if qtyTrim == "" {
			curRec.OrQty = 0
		} else {
			v, err := strconv.ParseInt(qtyTrim, 10, 64)
			if err != nil {
				filtered := ""
				for _, ch := range qtyTrim {
					if ch >= '0' && ch <= '9' {
						filtered += string(ch)
					}
				}
				if filtered == "" {
					curRec.OrQty = 0
				} else {
					v2, _ := strconv.ParseInt(filtered, 10, 64)
					curRec.OrQty = v2
				}
			} else {
				curRec.OrQty = v
			}
		}
		priceStr := txt[9:15]
		priceTrim := strings.TrimSpace(priceStr)
		if priceTrim == "" {
			curRec.OrPrice = decimal.NewFromInt(0)
		} else {
			v, err := strconv.ParseInt(priceTrim, 10, 64)
			if err != nil {
				filtered := ""
				for _, ch := range priceTrim {
					if ch >= '0' && ch <= '9' {
						filtered += string(ch)
					}
				}
				if filtered == "" {
					curRec.OrPrice = decimal.NewFromInt(0)
				} else {
					v2, _ := strconv.ParseInt(filtered, 10, 64)
					curRec.OrPrice = decimal.New(v2, -2)
				}
			} else {
				curRec.OrPrice = decimal.New(v, -2)
			}
		}
	} else {
		if err := orderScanner.Err(); err != nil {
			fmt.Fprintf(os.Stderr, "read error: %v\n", err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

func PROCESS_PARA() {
	WsTotal = decimal.NewFromInt(0)
	if curRec.OrQty == 0 {
		WsBadQty = (WsBadQty + 1) % 100
		fmt.Printf("%s BAD QTY\n", curRec.OrId)
	} else if curRec.OrStat == "N" {
		prod := decimal.NewFromInt(curRec.OrQty).Mul(curRec.OrPrice)
		trunc := prod.Truncate(2)
		WsTotal = storeDecimal(trunc, 8, 2)
		WsNewCount = (WsNewCount + 1) % 100
		SHOW_PARA()
	} else if curRec.OrStat == "S" {
		oneOhFive, _ := decimal.NewFromString("1.05")
		prod := decimal.NewFromInt(curRec.OrQty).Mul(curRec.OrPrice).Mul(oneOhFive)
		rounded := prod.Round(2)
		WsTotal = storeDecimal(rounded, 8, 2)
		WsShipCount = (WsShipCount + 1) % 100
		SHOW_PARA()
	} else if curRec.OrStat == "C" {
		WsCancelCount = (WsCancelCount + 1) % 100
		SHOW_PARA()
	} else {
		WsInvalid = (WsInvalid + 1) % 100
		fmt.Printf("%s BAD STATUS %s\n", curRec.OrId, curRec.OrStat)
	}
	sum := WsGrand.Add(WsTotal)
	WsGrand = storeDecimal(sum, 10, 2)
	READ_PARA()
}

func SHOW_PARA() {
	WsQtyEd = formatEdited(decimal.NewFromInt(curRec.OrQty), "ZZ9")
	WsPriceEd = formatEdited(curRec.OrPrice, "Z,ZZ9.99")
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s %s\n", curRec.OrId, curRec.OrStat, WsQtyEd, WsPriceEd, WsTotalEd)
}

func SUMMARY_PARA() {
	WsGrandEd = formatEdited(WsGrand, "Z,ZZZ,ZZZ,ZZ9.99")
	fmt.Printf("NEW: %02d SHIPPED: %02d CANCELLED: %02d\n", WsNewCount, WsShipCount, WsCancelCount)
	fmt.Printf("INVALID: %02d BAD QTY: %02d\n", WsInvalid, WsBadQty)
	fmt.Printf("GRAND TOTAL: %s\n", WsGrandEd)
}

func MAIN_PARA() {
	f, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			WsEofFlag = "Y"
			SUMMARY_PARA()
			return
		}
		fmt.Fprintf(os.Stderr, "failed to open input.dat: %v\n", err)
		os.Exit(1)
	}
	orderFile = f
	orderScanner = bufio.NewScanner(f)
	READ_PARA()
	for WsEofFlag != "Y" {
		PROCESS_PARA()
	}
	orderFile.Close()
	SUMMARY_PARA()
}

func main() {
	MAIN_PARA()
}
